 pf=P/f'sources/prompt-{slot:03}.txt';pf.write_text(prompt,encoding='utf-8');refs=[{'path':str(target),'role':'only edit target, exact whole-canvas translation/nearest4x'},{'path':str(P/'sources/original-east-master-common.png'),'role':'original master identity/material authority'},{'path':str(P/'sources/seed-reference.png'),'role':'provisional matched endpoint consistency, not pose authority'}]
